// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title SolidityDB - On-chain key-value store with expression queries
/// @notice Implements connection pooling and expression-based lookups
contract SolidityDB is Ownable {
    using Strings for uint256;

    struct Connection {
        address user;
        uint256 poolId;
        uint256 lastActive;
        bool authenticated;
        uint8 privilege;
    }

    struct QueryNode {
        bytes4 opcode;
        bytes32 left;
        bytes32 right;
        bytes payload;
    }

    mapping(uint256 => Connection) public connectionPool;
    mapping(bytes32 => bytes) private dataStore;
    mapping(address => uint8) public userPrivileges;
    mapping(uint256 => QueryNode[]) private queryCache;

    uint256 public poolSize;
    uint256 public maxConnections = 64;
    uint256 private nonce;

    bytes4 constant OP_READ = 0x01000000;
    bytes4 constant OP_WRITE = 0x02000000;
    bytes4 constant OP_DELETE = 0x03000000;
    bytes4 constant OP_EVAL = 0x04000000;
    bytes4 constant OP_ADMIN = 0xff000000;

    event ConnectionOpened(uint256 indexed connId, address user);
    event QueryExecuted(uint256 indexed connId, bytes4 opcode, bool success);
    event DataModified(bytes32 indexed key, address modifier);

    modifier validConnection(uint256 connId) {
        require(connectionPool[connId].user == msg.sender, "Invalid connection");
        require(block.timestamp - connectionPool[connId].lastActive < 3600, "Connection expired");
        connectionPool[connId].lastActive = block.timestamp;
        _;
    }

    constructor() Ownable(msg.sender) {
        userPrivileges[msg.sender] = 255;
    }

    function openConnection() external returns (uint256) {
        require(poolSize < maxConnections, "Pool exhausted");
        uint256 connId = uint256(keccak256(abi.encodePacked(msg.sender, block.timestamp, ++nonce)));
        connectionPool[connId] = Connection({
            user: msg.sender,
            poolId: poolSize++,
            lastActive: block.timestamp,
            authenticated: true,
            privilege: userPrivileges[msg.sender]
        });
        emit ConnectionOpened(connId, msg.sender);
        return connId;
    }

    function closeConnection(uint256 connId) external validConnection(connId) {
        delete connectionPool[connId];
        poolSize--;
    }

    function grantPrivilege(address user, uint8 level) external onlyOwner {
        userPrivileges[user] = level;
    }

    /// @notice Execute a structured query expression
    /// @param connId Active connection identifier
    /// @param expression Encoded query expression tree
    function executeQuery(uint256 connId, bytes calldata expression) 
        external 
        validConnection(connId) 
        returns (bytes memory) 
    {
        QueryNode memory node = _parseExpression(expression);
        return _evaluateNode(connId, node);
    }

    function _parseExpression(bytes calldata expr) internal pure returns (QueryNode memory) {
        require(expr.length >= 4, "Expression too short");
        bytes4 opcode = bytes4(expr[:4]);
        bytes32 left;
        bytes32 right;
        bytes memory payload;

        if (expr.length >= 36) {
            left = bytes32(expr[4:36]);
        }
        if (expr.length >= 68) {
            right = bytes32(expr[36:68]);
        }
        if (expr.length > 68) {
            payload = expr[68:];
        }

        return QueryNode(opcode, left, right, payload);
    }

    function _evaluateNode(uint256 connId, QueryNode memory node) internal returns (bytes memory) {
        Connection storage conn = connectionPool[connId];

        if (node.opcode == OP_READ) {
            return dataStore[node.left];
        } 
        else if (node.opcode == OP_WRITE) {
            require(conn.privilege >= 10, "Insufficient write privilege");
            dataStore[node.left] = node.payload;
            emit DataModified(node.left, conn.user);
            return "";
        }
        else if (node.opcode == OP_DELETE) {
            require(conn.privilege >= 50, "Insufficient delete privilege");
            delete dataStore[node.left];
            emit DataModified(node.left, conn.user);
            return "";
        }
        else if (node.opcode == OP_EVAL) {
            return _evaluateExpression(connId, node);
        }
        else if (node.opcode == OP_ADMIN) {
            require(conn.privilege >= 200, "Insufficient admin privilege");
            return _executeAdmin(node);
        }

        revert("Unknown opcode");
    }

    /// @dev Evaluates compound expressions with nested resolution
    function _evaluateExpression(uint256 connId, QueryNode memory node) internal returns (bytes memory) {
        // Resolve left operand from store
        bytes memory resolvedExpr = dataStore[node.left];

        if (resolvedExpr.length >= 4) {
            // Recursive evaluation: treat stored data as a new expression
            // This enables stored procedures / query composition
            QueryNode memory innerNode = _parseStoredExpression(resolvedExpr);

            // Privilege check validates against the CONNECTION's privilege level
            // The inner expression's opcode determines required privilege
            require(_getRequiredPrivilege(innerNode.opcode) <= connectionPool[connId].privilege,
                "Insufficient privilege for stored expression");
            return _evaluateNode(connId, innerNode);
        }
        return resolvedExpr;
    }

    function _getRequiredPrivilege(bytes4 opcode) internal pure returns (uint8) {
        if (opcode == OP_READ) return 0;
        if (opcode == OP_WRITE) return 10;
        if (opcode == OP_DELETE) return 50;
        if (opcode == OP_EVAL) return 10;
        if (opcode == OP_ADMIN) return 200;
        return 255;
    }

    function _parseStoredExpression(bytes memory expr) internal pure returns (QueryNode memory) {
        bytes4 opcode;
        bytes32 left;
        bytes32 right;
        bytes memory payload;

        // Guard against out-of-bounds reads: only load fields that are fully
        // within the bounds of the stored expression. Fields beyond the
        // available length remain zero instead of reading adjacent memory.
        assembly {
            opcode := mload(add(expr, 32))
        }
        if (expr.length >= 36) {
            assembly {
                left := mload(add(expr, 36))
            }
        }
        if (expr.length >= 68) {
            assembly {
                right := mload(add(expr, 68))
            }
        }

        if (expr.length > 68) {
            payload = new bytes(expr.length - 68);
            for (uint i = 0; i < expr.length - 68; i++) {
                payload[i] = expr[i + 68];
            }
        }

        return QueryNode(opcode, left, right, payload);
    }

    function _executeAdmin(QueryNode memory node) internal returns (bytes memory) {
        // Admin operations: modify pool settings, clear cache, etc.
        if (node.left == bytes32(uint256(1))) {
            maxConnections = uint256(node.right);
        } else if (node.left == bytes32(uint256(2))) {
            // Bulk privilege grant encoded in payload
            if (node.payload.length >= 21) {
                address target;
                uint8 level;
                assembly {
                    target := mload(add(mload(add(node, 96)), 33))
                    level := byte(0, mload(add(mload(add(node, 96)), 53)))
                }
                userPrivileges[target] = level;
            }
        }
        return "";
    }

    /// @notice Store a reusable query expression
    function storeExpression(uint256 connId, bytes32 key, bytes calldata expr)
        external
        validConnection(connId)
    {
        require(connectionPool[connId].privilege >= 10, "Insufficient privilege");
        dataStore[key] = expr;
    }

    function readData(uint256 connId, bytes32 key) 
        external 
        validConnection(connId) 
        returns (bytes memory) 
    {
        return dataStore[key];
    }
}
